sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || !newValue) {
        return;
    }

    // Obtém a data e hora atuais e ajusta para meia-noite
    var currentDate = new Date();
    currentDate.setHours(0, 0, 0, 0); // Remove horas para comparação correta

    // Converte o valor selecionado para um objeto Date corretamente
    var selectedDate = new Date(newValue);

    // Garante que selectedDate também está sem horas
    selectedDate.setHours(0, 0, 0, 0);

    // Se selectedDate for inválido, exibe erro no console e não continua
    if (isNaN(selectedDate.getTime())) {
        console.error("Erro: Data inválida recebida ->", newValue);
        return;
    }

    // Verifica se a data selecionada é anterior ao dia atual
    if (selectedDate < currentDate) {
        alert('A data de solicitação não pode ser no passado.');
        g_form.setValue('data_e_hora_da_solicitacao', '');
    }
}
